import{_ as t,I as a,g as i,j as s}from"./chunks/framework.DnGoLYRz.js";const g=JSON.parse('{"title":"getting started","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md"}'),o={name:"getting-started.md"};function n(r,e,l,h,d,p){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="getting-started" tabindex="-1">getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;getting started&quot;">​</a></h1><p>Three things get you writing ghūl: an editor, the .NET SDK, and some ghūl code to start from. The compiler is not on the list - a ghūl repository pins it as a local .NET tool, so it arrives with the code.</p><h2 id="prerequisites" tabindex="-1">prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;prerequisites&quot;">​</a></h2><p>Two things to have in place before the code: an editor, and the .NET SDK.</p><h3 id="an-editor" tabindex="-1">an editor <a class="header-anchor" href="#an-editor" aria-label="Permalink to &quot;an editor&quot;">​</a></h3><p><a href="https://code.visualstudio.com" target="_blank" rel="noreferrer">Visual Studio Code</a> with the <a href="https://marketplace.visualstudio.com/items?itemName=degory.ghul" target="_blank" rel="noreferrer">ghūl language extension</a> gives you errors and warnings as you type, completion, hover, go to definition, rename and formatting.</p><p>The extension is an ordinary Visual Studio Code extension, so any editor that can install VS Code extensions gets ghūl support out of the box. Other editors can drive the underlying language server directly - see <a href="/tooling.html#other-editors">other editors</a> on the tooling page.</p><h3 id="the-net-sdk" tabindex="-1">the .NET SDK <a class="header-anchor" href="#the-net-sdk" aria-label="Permalink to &quot;the .NET SDK&quot;">​</a></h3><p>ghūl is hosted on .NET: the compiler runs on the <a href="https://dotnet.microsoft.com/en-us/download/dotnet/10.0" target="_blank" rel="noreferrer">.NET 10 SDK</a>, and the assemblies it produces target .NET 10.</p><p>You can skip installing anything locally: the repositories below ship a dev container, so opening one in a GitHub Codespace, or in VS Code with the Dev Containers extension, gives you the SDK, the compiler and the language extension ready to go.</p><h2 id="some-ghul-code" tabindex="-1">some ghūl code <a class="header-anchor" href="#some-ghul-code" aria-label="Permalink to &quot;some ghūl code&quot;">​</a></h2><ul><li>The <a href="https://github.com/degory/ghul-scratchpad" target="_blank" rel="noreferrer">ghūl scratchpad</a> is a minimal one-file project: open it in a Codespace or clone it, paste any example from this site into <code class="ghul-inline-plain">main.ghul</code>, and <code class="ghul-inline"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">dotnet</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> run</span></code>.</li><li>The <a href="https://github.com/degory/ghul-examples" target="_blank" rel="noreferrer">examples repository</a> has fuller, runnable examples organised by topic.</li></ul><p>Both pin the ghūl compiler as a local .NET tool, so there is nothing separate to install: <code class="ghul-inline"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">dotnet</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> tool</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> restore</span></code> fetches it, and the dev containers run that for you.</p><h2 id="it-s-all-ordinary-net" tabindex="-1">it&#39;s all ordinary .NET <a class="header-anchor" href="#it-s-all-ordinary-net" aria-label="Permalink to &quot;it&#39;s all ordinary .NET&quot;">​</a></h2><p>A ghūl project is a normal .NET SDK project. In either repository you&#39;ll find a <code class="ghul-inline-plain">.ghulproj</code> - an MSBuild project file with the usual things in it - and the normal <code class="ghul-inline-plain">dotnet</code> commands work as you&#39;d expect:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">dotnet</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> build</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">dotnet</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> run</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">dotnet</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> test</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">dotnet</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> pack</span></span></code></pre></div><p>A ghūl project can reference NuGet packages, produce libraries or executables, and be packed and published exactly like a C# project.</p><p>To start a project of your own - from a template, from the repository template, or from scratch - see <a href="/tooling.html#creating-a-project">creating a project</a> on the tooling page.</p>`,18)])])}const u=t(o,[["render",n]]);export{g as __pageData,u as default};
